function normalizeText(text) {
  return text.toLowerCase().replace(/[！-～]/g, function(s) {
    return String.fromCharCode(s.charCodeAt(0) - 65248);
  }).replace(/[""]/g, '"').replace(/['']/g, "'").replace(/[（）]/g, function(s) {
    return s === "（" ? "(" : ")";
  });
}

